import{_ as l,a0 as t,w as d,s as o,ao as r,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"簡明指南：使用 bind 設置 DNS 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"簡明指南：使用 bind 設置 DNS 服務器 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"簡明指南：使用 bind 設置 DNS 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"簡明指南：使用 bind 設置 DNS 服務器 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200113 How to setup a DNS server with bind","title":"簡明指南：使用 bind 設置 DNS 服務器","tag":"202003","desc":""},"relativePath":"202003/20200113 How to setup a DNS server with bind.md","filePath":"[post].md"}'),c={name:"202003/20200113 How to setup a DNS server with bind.md"};function h(g,s,k,b,u,f){const n=t("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="簡明指南-使用-bind-設置-dns-服務器" tabindex="-1">簡明指南：使用 bind 設置 DNS 服務器 <a class="header-anchor" href="#簡明指南-使用-bind-設置-dns-服務器" aria-label="Permalink to “簡明指南：使用 bind 設置 DNS 服務器”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/01/dns-server-bind-1-816x345.png" alt=""></p><p><ruby>域名系統<rt>Domain Name System</rt></ruby>，我們更通常稱為 DNS 的系統，可以將域名翻譯或轉換為與該域關聯的 IP 地址。DNS 是能夠讓你通過名稱找到自己喜歡的網站而不是在瀏覽器中輸入 IP 地址的原因。本指南將向你展示如何配置一個主 DNS 系統以及客户端。</p><p>以下是本文示例中使用的系統細節：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dns01.fedora.local    （192.168.1.160）- 主 DNS 服務器</span></span>
<span class="line"><span>client.fedora.local     （192.168.1.136）- 客户端</span></span></code></pre></div><h3 id="dns-服務器配置" tabindex="-1">DNS 服務器配置 <a class="header-anchor" href="#dns-服務器配置" aria-label="Permalink to “DNS 服務器配置”">​</a></h3><p>使用 <code>sudo</code> 安裝 bind 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install bind bind-utils -y</span></span></code></pre></div><p>bind 包提供了 <code>/etc/named.conf</code> 配置文件，來供你配置 DNS 服務器。</p><p>編輯 <code>/etc/named.conf</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo vi /etc/named.conf</span></span></code></pre></div><p>查找以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>listen-on port 53 { 127.0.0.1; };</span></span></code></pre></div><p>添加主 DNS 服務器的 IP 地址，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>listen-on port 53 { 127.0.0.1; 192.168.1.160; };</span></span></code></pre></div><p>查找以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>allow-query  { localhost; };</span></span></code></pre></div><p>添加本地網絡範圍。該示例系統使用的 IP 地址在 192.168.1.X 的範圍內。指定如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>allow-query  { localhost; 192.168.1.0/24; };</span></span></code></pre></div><p>指定轉發和反向區域。<ruby>區域文件<rt>Zone file</rt></ruby>就是具有系統上 DNS 信息（例如 IP 地址和主機名）的文本文件。<ruby>轉發區域文件<rt>forward zone file</rt></ruby>使得將主機名轉換為 IP 地址成為可能。<ruby>反向區域文件<rt>reverse zone file</rt></ruby>則相反。它允許遠程系統將 IP 地址轉換為主機名。</p><p>在 <code>/etc/named.conf</code> 文件的底部查找以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>include &quot;/etc/named.rfc1912.zones&quot;;</span></span></code></pre></div><p>在此處，你將在<strong>該行的正上方</strong>指定區域文件信息，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zone &quot;dns01.fedora.local&quot; IN {</span></span>
<span class="line"><span>  type master;</span></span>
<span class="line"><span>  file &quot;forward.fedora.local&quot;;</span></span>
<span class="line"><span>  allow-update { none; };</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>zone &quot;1.168.192.in-addr.arpa&quot; IN {</span></span>
<span class="line"><span>  type master;</span></span>
<span class="line"><span>  file &quot;reverse.fedora.local&quot;;</span></span>
<span class="line"><span>  allow-update { none; };</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><code>forward.fedora.local</code> 和 <code>reverse.fedora.local</code> 文件是要創建的區域文件的名稱。它們可以是任意名字。</p><p>保存並退出。</p><h4 id="創建區域文件" tabindex="-1">創建區域文件 <a class="header-anchor" href="#創建區域文件" aria-label="Permalink to “創建區域文件”">​</a></h4><p>創建你在 <code>/etc/named.conf</code> 文件中指定的轉發和反向區域文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /var/named/forward.fedora.local</span></span></code></pre></div><p>添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$TTL 86400</span></span>
<span class="line"><span>@   IN  SOA     dns01.fedora.local. root.fedora.local. (</span></span>
<span class="line"><span>        2011071001  ;Serial</span></span>
<span class="line"><span>        3600        ;Refresh</span></span>
<span class="line"><span>        1800        ;Retry</span></span>
<span class="line"><span>        604800      ;Expire</span></span>
<span class="line"><span>        86400       ;Minimum TTL</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>@       IN  NS          dns01.fedora.local.</span></span>
<span class="line"><span>@       IN  A           192.168.1.160</span></span>
<span class="line"><span>dns01           IN  A   192.168.1.160</span></span>
<span class="line"><span>client          IN  A   192.168.1.136</span></span></code></pre></div><p>所有<strong>粗體</strong>（LCTT 譯註：本譯文中無法呈現粗體）內容都特定於你的環境。保存文件並退出。接下來，編輯 <code>reverse.fedora.local</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /var/named/reverse.fedora.local</span></span></code></pre></div><p>添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$TTL 86400</span></span>
<span class="line"><span>@   IN  SOA     dns01.fedora.local. root.fedora.local. (</span></span>
<span class="line"><span>        2011071001  ;Serial</span></span>
<span class="line"><span>        3600        ;Refresh</span></span>
<span class="line"><span>        1800        ;Retry</span></span>
<span class="line"><span>        604800      ;Expire</span></span>
<span class="line"><span>        86400       ;Minimum TTL</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>@       IN  NS          dns01.fedora.local.</span></span>
<span class="line"><span>@       IN  PTR         fedora.local.</span></span>
<span class="line"><span>dns01           IN  A   192.168.1.160</span></span>
<span class="line"><span>client          IN  A   192.168.1.136</span></span>
<span class="line"><span>160     IN  PTR         dns01.fedora.local.</span></span>
<span class="line"><span>136     IN  PTR         client.fedora.local.</span></span></code></pre></div><p>所有<strong>粗體</strong>（LCTT 譯註：本譯文中無法呈現粗體）內容都特定於你的環境。保存文件並退出。</p><p>你還需要配置 SELinux 併為配置文件添加正確的所有權。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chgrp named -R /var/named</span></span>
<span class="line"><span>sudo chown -v root:named /etc/named.conf</span></span>
<span class="line"><span>sudo restorecon -rv /var/named</span></span>
<span class="line"><span>sudo restorecon /etc/named.conf</span></span></code></pre></div><p>配置防火牆：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo firewall-cmd --add-service=dns --perm</span></span>
<span class="line"><span>sudo firewall-cmd --reload</span></span></code></pre></div><h4 id="檢查配置是否存在語法錯誤" tabindex="-1">檢查配置是否存在語法錯誤 <a class="header-anchor" href="#檢查配置是否存在語法錯誤" aria-label="Permalink to “檢查配置是否存在語法錯誤”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo named-checkconf /etc/named.conf</span></span></code></pre></div><p>如果沒有輸出或返回錯誤，那麼你的配置有效。</p><p>檢查轉發和反向區域文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo named-checkzone forward.fedora.local /var/named/forward.fedora.local</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo named-checkzone reverse.fedora.local /var/named/reverse.fedora.local</span></span></code></pre></div><p>你應該看到 “OK” 的響應：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zone forward.fedora.local/IN: loaded serial 2011071001</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span></span></span>
<span class="line"><span>zone reverse.fedora.local/IN: loaded serial 2011071001</span></span>
<span class="line"><span>OK</span></span></code></pre></div><h4 id="啓用並啓動-dns-服務" tabindex="-1">啓用並啓動 DNS 服務 <a class="header-anchor" href="#啓用並啓動-dns-服務" aria-label="Permalink to “啓用並啓動 DNS 服務”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable named</span></span>
<span class="line"><span>$ sudo systemctl start named</span></span></code></pre></div><h4 id="配置-resolv-conf-文件" tabindex="-1">配置 resolv.conf 文件 <a class="header-anchor" href="#配置-resolv-conf-文件" aria-label="Permalink to “配置 resolv.conf 文件”">​</a></h4><p>編輯 <code>/etc/resolv.conf</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/resolv.conf</span></span></code></pre></div><p>查找你當前的 <code>nameserver</code> 行。在示例系統上，使用調製解調器/路由器充當名稱服務器，因此當前看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 192.168.1.1</span></span></code></pre></div><p>這需要更改為主 DNS 服務器的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 192.168.1.160</span></span></code></pre></div><p>保存更改並退出。</p><p>不幸的是需要注意一點。如果系統重啓或網絡重啓，那麼 NetworkManager 會覆蓋 <code>/etc/resolv.conf</code> 文件。這意味着你將丟失所做的所有更改。</p><p>為了防止這種情況發生，請將 <code>/etc/resolv.conf</code> 設為不可變：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chattr +i /etc/resolv.conf</span></span></code></pre></div><p>如果要重新設置，就需要允許其再次被覆蓋：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chattr -i /etc/resolv.conf</span></span></code></pre></div><h4 id="測試-dns-服務器" tabindex="-1">測試 DNS 服務器 <a class="header-anchor" href="#測試-dns-服務器" aria-label="Permalink to “測試 DNS 服務器”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig fedoramagazine.org</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>; &lt;&lt;&gt;&gt; DiG 9.11.13-RedHat-9.11.13-2.fc30 &lt;&lt;&gt;&gt; fedoramagazine.org</span></span>
<span class="line"><span>;; global options: +cmd</span></span>
<span class="line"><span>;; Got answer:</span></span>
<span class="line"><span>;; -&gt;&gt;HEADER&lt;&lt;- opcode: QUERY, status: NOERROR, id: 8391</span></span>
<span class="line"><span>;; flags: qr rd ra; QUERY: 1, ANSWER: 1, AUTHORITY: 3, ADDITIONAL: 6</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; OPT PSEUDOSECTION:</span></span>
<span class="line"><span> ; EDNS: version: 0, flags:; udp: 4096</span></span>
<span class="line"><span> ; COOKIE: c7350d07f8efaa1286c670ab5e13482d600f82274871195a (good)</span></span>
<span class="line"><span> ;; QUESTION SECTION:</span></span>
<span class="line"><span> ;fedoramagazine.org.        IN  A</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; ANSWER SECTION:</span></span>
<span class="line"><span> fedoramagazine.org.    50  IN  A   35.197.52.145</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; AUTHORITY SECTION:</span></span>
<span class="line"><span> fedoramagazine.org.    86150   IN  NS  ns05.fedoraproject.org.</span></span>
<span class="line"><span> fedoramagazine.org.    86150   IN  NS  ns02.fedoraproject.org.</span></span>
<span class="line"><span> fedoramagazine.org.    86150   IN  NS  ns04.fedoraproject.org.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; ADDITIONAL SECTION:</span></span>
<span class="line"><span> ns02.fedoraproject.org.    86150   IN  A   152.19.134.139</span></span>
<span class="line"><span> ns04.fedoraproject.org.    86150   IN  A   209.132.181.17</span></span>
<span class="line"><span> ns05.fedoraproject.org.    86150   IN  A   85.236.55.10</span></span>
<span class="line"><span> ns02.fedoraproject.org.    86150   IN  AAAA    2610:28:3090:3001:dead:beef:cafe:fed5</span></span>
<span class="line"><span> ns05.fedoraproject.org.    86150   IN  AAAA    2001:4178:2:1269:dead:beef:cafe:fed5</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ;; Query time: 830 msec</span></span>
<span class="line"><span> ;; SERVER: 192.168.1.160#53(192.168.1.160)</span></span>
<span class="line"><span> ;; WHEN: Mon Jan 06 08:46:05 CST 2020</span></span>
<span class="line"><span> ;; MSG SIZE  rcvd: 266</span></span></code></pre></div><p>需要檢查幾件事以驗證 DNS 服務器是否正常運行。顯然，取得結果很重要，但這本身並不意味着 DNS 服務器實際上正常工作。</p><p>頂部的 <code>QUERY</code>、<code>ANSWER</code> 和 <code>AUTHORITY</code> 字段應顯示為非零，如我們的示例所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>;; flags: qr rd ra; QUERY: 1, ANSWER: 1, AUTHORITY: 3, ADDITIONAL: 6</span></span></code></pre></div><p>並且 <code>SERVER</code> 字段應有你的 DNS 服務器的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>;; SERVER: 192.168.1.160#53(192.168.1.160)</span></span></code></pre></div><p>如果這是你第一次運行 <code>dig</code> 命令，請注意完成查詢要花費 830 毫秒的時間：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>;; Query time: 830 msec</span></span></code></pre></div><p>如果再次運行它，查詢將會更快：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig fedoramagazine.org</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>;; Query time: 0 msec</span></span>
<span class="line"><span>;; SERVER: 192.168.1.160#53(192.168.1.160)</span></span></code></pre></div><h3 id="客户端配置" tabindex="-1">客户端配置 <a class="header-anchor" href="#客户端配置" aria-label="Permalink to “客户端配置”">​</a></h3><p>客户端配置將簡單得多。</p><p>安裝 bind 程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install bind-utils -y</span></span></code></pre></div><p>編輯 <code>/etc/resolv.conf</code> 文件，並將主 DNS 配置為唯一的名稱服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/resolv.conf</span></span></code></pre></div><p>它看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nameserver 192.168.1.160</span></span></code></pre></div><p>保存更改並退出。然後，使 <code>/etc/resolv.conf</code> 文件不可變，防止其被覆蓋並變回默認設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chattr +i /etc/resolv.conf</span></span></code></pre></div><h4 id="測試客户端" tabindex="-1">測試客户端 <a class="header-anchor" href="#測試客户端" aria-label="Permalink to “測試客户端”">​</a></h4><p>你應該獲得與 DNS 服務器相同的結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig fedoramagazine.org</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>; &lt;&lt;&gt;&gt; DiG 9.11.13-RedHat-9.11.13-2.fc30 &lt;&lt;&gt;&gt; fedoramagazine.org</span></span>
<span class="line"><span>;; global options: +cmd</span></span>
<span class="line"><span>;; Got answer:</span></span>
<span class="line"><span>;; -&gt;&gt;HEADER&lt;&lt;- opcode: QUERY, status: NOERROR, id: 8391</span></span>
<span class="line"><span>;; flags: qr rd ra; QUERY: 1, ANSWER: 1, AUTHORITY: 3, ADDITIONAL: 6</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; OPT PSEUDOSECTION:</span></span>
<span class="line"><span> ; EDNS: version: 0, flags:; udp: 4096</span></span>
<span class="line"><span> ; COOKIE: c7350d07f8efaa1286c670ab5e13482d600f82274871195a (good)</span></span>
<span class="line"><span> ;; QUESTION SECTION:</span></span>
<span class="line"><span> ;fedoramagazine.org.        IN  A</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; ANSWER SECTION:</span></span>
<span class="line"><span> fedoramagazine.org.    50  IN  A   35.197.52.145</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; AUTHORITY SECTION:</span></span>
<span class="line"><span> fedoramagazine.org.    86150   IN  NS  ns05.fedoraproject.org.</span></span>
<span class="line"><span> fedoramagazine.org.    86150   IN  NS  ns02.fedoraproject.org.</span></span>
<span class="line"><span> fedoramagazine.org.    86150   IN  NS  ns04.fedoraproject.org.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>;; ADDITIONAL SECTION:</span></span>
<span class="line"><span> ns02.fedoraproject.org.    86150   IN  A   152.19.134.139</span></span>
<span class="line"><span> ns04.fedoraproject.org.    86150   IN  A   209.132.181.17</span></span>
<span class="line"><span> ns05.fedoraproject.org.    86150   IN  A   85.236.55.10</span></span>
<span class="line"><span> ns02.fedoraproject.org.    86150   IN  AAAA    2610:28:3090:3001:dead:beef:cafe:fed5</span></span>
<span class="line"><span> ns05.fedoraproject.org.    86150   IN  AAAA    2001:4178:2:1269:dead:beef:cafe:fed5</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ;; Query time: 1 msec</span></span>
<span class="line"><span> ;; SERVER: 192.168.1.160#53(192.168.1.160)</span></span>
<span class="line"><span> ;; WHEN: Mon Jan 06 08:46:05 CST 2020</span></span>
<span class="line"><span> ;; MSG SIZE  rcvd: 266</span></span></code></pre></div><p>確保 <code>SERVER</code> 輸出的是你 DNS 服務器的 IP 地址。</p><p>你的 DNS 服務器設置完成了，現在所有來自客户端的請求都會經過你的 DNS 服務器了！</p><hr>`,92)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://fedoramagazine.org/how-to-setup-a-dns-server-with-bind/"},{default:i(()=>[...s[0]||(s[0]=[a("https://fedoramagazine.org/how-to-setup-a-dns-server-with-bind/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://fedoramagazine.org/author/rcurtiswarfield/"},{default:i(()=>[...s[2]||(s[2]=[a("Curt Warfield",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const N=l(c,[["render",h]]);export{v as __pageData,N as default};
